use std::marker::PhantomData;

struct Disconnected;

struct Connection<S> {
    log: Vec<String>,
    _state: PhantomData<S>,
}

impl Connection<Disconnected> {
    fn new() -> Self {
        Connection { log: Vec::new(), _state: PhantomData }
    }
}

fn main() {
    let c = Connection::new();
    println!("{} log lines", c.log.len());
}
